import { useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { getJson, putJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useRealToday } from '../session/session';
import { claimsQueryKey } from '../claims/claims';
import { poolsQueryKey } from '../pools/pools';
import { peoplePath, peopleQueryKey, useSelectedPeople, useShowRetired, type Person } from './people';

// Retires every selected person from a date (blank: the sheet's today) with one button, in list order. Each is
// retired exactly as the row's retire does, so the server writes the same PERSON_RETIRED and rollup lines; one it
// refuses is left as it is. The count of people retired shows once all are done, and is gone while it runs; the
// selection is cleared.
function BulkRetire() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useRealToday();
  const [showRetired] = useShowRetired();
  const { selected, clear } = useSelectedPeople();
  const queryClient = useQueryClient();
  const [date, setDate] = useState('');
  const [result, setResult] = useState<{ retired: number; refused: number } | null>(null);
  const busy = useRef(false);
  if (!user || !sheet) return null;

  const run = async () => {
    if (busy.current) return;
    busy.current = true;
    setResult(null);
    try {
      let retired = 0;
      let refused = 0;
      try {
        const people = await queryClient.fetchQuery({
          queryKey: peopleQueryKey(sheet),
          queryFn: () => getJson<Person[]>(peoplePath(sheet)),
          staleTime: 0,
        });
        const order = people.filter((p) => (showRetired || p.retiredFrom === null) && selected.has(p.id));
        for (const p of order) {
          try {
            await putJson<Person>(`${peoplePath(sheet)}/${p.id}/retire`, { date: date.trim() }, user);
            retired++;
          } catch {
            refused++;
          }
        }
      } catch {
        refused++;
      }
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) });
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      await queryClient.invalidateQueries({ queryKey: poolsQueryKey(sheet) });
      clear();
      setResult({ retired, refused });
    } finally {
      busy.current = false;
    }
  };

  return (
    <div>
      <input
        data-testid="bulk-retire-date"
        placeholder={today ?? 'Retire from (YYYY-MM-DD)'}
        value={date}
        onChange={(e) => { setDate(e.target.value); setResult(null); }}
      />{' '}
      <button type="button" data-testid="bulk-retire" onClick={() => void run()}>
        Retire selected people
      </button>
      {result && (
        <>
          {' '}Retired <span data-testid="bulk-retired">{result.retired}</span>
          {result.retired === 0 && result.refused > 0 && (
            <>{' '}<span data-testid="person-error">The people could not be retired.</span></>
          )}
        </>
      )}
    </div>
  );
}

export const contribution = HomeMain.fill({ order: 20.6, Component: BulkRetire });
import { useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { getJson, putJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsQueryKey } from '../claims/claims';
import { peoplePath, peopleQueryKey, useSelectedPeople, useShowRetired, type Person } from './people';
import { useGradeCodes } from '../grades/grades';

// Gives every selected person a grade from a date (blank: the sheet's today) with one button, in list order. Each
// is saved exactly as the person form would save them (same name, terms, contact and tags, the version as the store holds it now),
// so the server writes the same PERSON_EDITED and rollup lines; one it refuses is left as it is. The count of
// people changed shows once all are done, and is gone while it runs; the selection is cleared.

function SelectHeader() {
  return <th>Select</th>;
}

function PersonSelect({ person }: { person: Person }) {
  const { selected, toggle } = useSelectedPeople();
  return (
    <td>
      <input
        type="checkbox"
        data-testid="person-select"
        checked={selected.has(person.id)}
        onChange={(e) => toggle(person.id, e.target.checked)}
      />
    </td>
  );
}

function BulkGrade() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [showRetired] = useShowRetired();
  const { selected, clear } = useSelectedPeople();
  const queryClient = useQueryClient();
  const gradeCodes = useGradeCodes();
  const [grade, setGrade] = useState('A');
  const [from, setFrom] = useState('');
  const [result, setResult] = useState<{ graded: number; refused: number } | null>(null);
  const busy = useRef(false);
  if (!user || !sheet) return null;

  const run = async () => {
    if (busy.current) return;
    busy.current = true;
    setResult(null);
    try {
      let graded = 0;
      let refused = 0;
      try {
        const people = await queryClient.fetchQuery({
          queryKey: peopleQueryKey(sheet),
          queryFn: () => getJson<Person[]>(peoplePath(sheet)),
          staleTime: 0,
        });
        const order = people.filter((p) => (showRetired || p.retiredFrom === null) && selected.has(p.id));
        for (const p of order) {
          try {
            await putJson<Person>(`${peoplePath(sheet)}/${p.id}`, {
              name: p.name,
              grade,
              gradeFrom: from.trim(),
              terms: p.terms == null ? '' : String(p.terms),
              contact: p.contact ?? '',
              tags: (p.tags ?? []).join(', '),
              version: p.version,
            }, user);
            graded++;
          } catch {
            refused++;
          }
        }
      } catch {
        refused++;
      }
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) });
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      clear();
      setResult({ graded, refused });
    } finally {
      busy.current = false;
    }
  };

  return (
    <div>
      <select data-testid="bulk-grade" value={grade} onChange={(e) => { setGrade(e.target.value); setResult(null); }}>
        {gradeCodes.map((g) => (
          <option key={g} value={g}>{g}</option>
        ))}
      </select>{' '}
      <input
        data-testid="bulk-grade-from"
        placeholder="Grade from (YYYY-MM-DD)"
        value={from}
        onChange={(e) => { setFrom(e.target.value); setResult(null); }}
      />{' '}
      <button type="button" data-testid="bulk-grade-apply" onClick={() => void run()}>
        Grade selected people
      </button>
      {result && (
        <>
          {' '}Changed <span data-testid="bulk-graded">{result.graded}</span>
          {result.graded === 0 && result.refused > 0 && (
            <>{' '}<span data-testid="person-error">The grade could not be given.</span></>
          )}
        </>
      )}
    </div>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 1, Component: SelectHeader }),
  PersonCells.fill({ order: 1, Component: PersonSelect }),
  HomeMain.fill({ order: 20.5, Component: BulkGrade }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { useRowAction } from '../../api/rowAction';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useRealToday } from '../session/session';
import { peoplePath, peopleQueryKey, type Person } from './people';
import { useColumnShown } from './columns';

// Whether a person has any hold, a line for each of their holds, and the from-date (blank: the sheet's today),
// to-date (blank: open-ended) and button that add a hold. Their OPEN claims dated within a hold count in no live
// total, unless a statement binds them; their other claims still count. A hold ends on its to-date.
function HoldHeader() {
  return <th>Hold</th>;
}

function PersonHold({ person }: { person: Person }) {
  const shown = useColumnShown('hold');
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useRealToday();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const hold = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      putJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/hold`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') });
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(hold);
  const rowAction = useRowAction(`person-${person.id}`);
  return (
    <td>
      {shown && <><span data-testid="person-hold">{person.held ? 'yes' : 'no'}</span>{' '}</>}
      {person.holds.map((h, i) => (
        <span key={i} data-testid="person-hold-line">{h.from} – {h.to ?? 'open'}{' '}</span>
      ))}
      <input
        data-testid="person-hold-from"
        placeholder={today ?? 'from'}
        value={from}
        onChange={(e) => { setFrom(e.target.value); hold.reset(); }}
      />
      <input
        data-testid="person-hold-to"
        placeholder="to (open)"
        value={to}
        onChange={(e) => { setTo(e.target.value); hold.reset(); }}
      />
      <button type="button" data-testid="person-hold-toggle" disabled={hold.isPending} onClick={() => { rowAction.take(); submit({ from, to }); }}>
        Hold
      </button>
      {hold.isError && rowAction.isLatest && <span data-testid="person-error">The hold's dates must be calendar dates, the to-date not before the from-date.</span>}
    </td>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 45, Component: HoldHeader }),
  PersonCells.fill({ order: 45, Component: PersonHold }),
];
